import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const c=JSON.parse('{"title":"Σημειώσεις εκδόσεων","description":"","frontmatter":{},"headers":[],"relativePath":"el/release-notes/index.md","filePath":"el/release-notes/index.md"}'),n={name:"el/release-notes/index.md"};function i(s,a,l,h,d,p){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="σημειωσεις-εκδοσεων" tabindex="-1">Σημειώσεις εκδόσεων <a class="header-anchor" href="#σημειωσεις-εκδοσεων" aria-label="Permalink to &quot;Σημειώσεις εκδόσεων&quot;">​</a></h1><p>Για αναλυτικό ιστορικό ανά έκδοση δείτε <a href="/el/changelog/">Ιστορικό αλλαγών</a>. Οι νεότερες συνόψεις προέρχονται από δημοσιευμένες καταγραφές εκδόσεων και δεν πιστοποιούν ενεργοποίηση παραγωγής.</p><h2 id="v0-7-21-—-2026-11-26" tabindex="-1">v0.7.21 — 2026-11-26 <a class="header-anchor" href="#v0-7-21-—-2026-11-26" aria-label="Permalink to &quot;v0.7.21 — 2026-11-26&quot;">​</a></h2><p>Βελτίωση ελαχιστοποίησης δεδομένων προς AI, τοπική ανασύνθεση στοιχείων επικοινωνίας, αναγνώριση CRM, ανίχνευση αντικρουόμενων στοιχείων, ειδοποιήσεις κύκλου κράτησης και ετοιμότητα ένταξης εταιρείας. Ατομική αποθήκευση συνομιλιών με προστασία επαναφοράς, ανάληψη από χειριστή, έλεγχος ιδιοκτησίας συνομιλίας και προστασία επιλογής αποθηκευμένων τοποθεσιών και ιδιωτικών προτιμήσεων CRM.</p><p><strong>Διαθεσιμότητα:</strong> η δημοσίευση δεν επιβεβαιώνει εγκατάσταση ή εμπορική ενεργοποίηση.</p><h2 id="v0-7-20-—-2026-11-25" tabindex="-1">v0.7.20 — 2026-11-25 <a class="header-anchor" href="#v0-7-20-—-2026-11-25" aria-label="Permalink to &quot;v0.7.20 — 2026-11-25&quot;">​</a></h2><p>Ταχεία αναζήτηση πελατών, αναγνώριση επαναλαμβανόμενων επιβατών, κράτηση με τηλέφωνο και προαιρετικό email, ροή με προτεραιότητα στα μετρητά, εκτίμηση προμήθειας συνεργάτη, ασφαλείς συνόψεις κράτησης και υποδομή καναλιών μηνυμάτων. Ένταξη εταιρείας, συνέχεια συνομιλιών AI Copilot, παρουσίαση κατάστασης κράτησης και τιμής και ενημέρωση αντιγραφής.</p><p><strong>Διαθεσιμότητα:</strong> η δημοσίευση δεν επιβεβαιώνει εγκατάσταση ή εμπορική ενεργοποίηση.</p><h2 id="v0-7-19-—-2026-11-25" tabindex="-1">v0.7.19 — 2026-11-25 <a class="header-anchor" href="#v0-7-19-—-2026-11-25" aria-label="Permalink to &quot;v0.7.19 — 2026-11-25&quot;">​</a></h2><p>Διαδρομές οδηγών και προστασίες τροποποιήσεων, μερική και πλήρης είσπραξη μετρητών, καταγραφή οδηγού είσπραξης, συμφωνία και παράδοση μετρητών, CRM, επαναλαμβανόμενες κρατήσεις, κρατήσεις συνεργατών concierge, AI και ένταξη εταιρείας. Ανίχνευση αποτυχίας ενημέρωσης, ανάκτηση μετά από λήξη χρόνου παρακολούθησης εγκατάστασης και ασφαλέστερη επαλήθευση επανάληψης.</p><p><strong>Διαθεσιμότητα:</strong> η δημοσίευση δεν επιβεβαιώνει εγκατάσταση ή εμπορική ενεργοποίηση.</p><h2 id="v0-7-18-—-2026-11-25" tabindex="-1">v0.7.18 — 2026-11-25 <a class="header-anchor" href="#v0-7-18-—-2026-11-25" aria-label="Permalink to &quot;v0.7.18 — 2026-11-25&quot;">​</a></h2><p>Ανεξάρτητες αναθέσεις μετάβασης και επιστροφής, χωριστή πρόοδος οδηγού, επιβεβαίωση μετρητών οδηγού, εκτυπώσιμα παραστατικά διαδρομής, διευρυμένες αναφορές και λίστα ετοιμότητας εταιρείας. Διεπαφή άμεσης ενημέρωσης, ειδοποίηση στην κεφαλίδα, παρακολούθηση εγκατάστασης, συμπτυγμένα διαγνωστικά, παράδοση μετρητών, ανίχνευση συγκρούσεων αναθέσεων, κρατήσεις και AI Copilot.</p><p><strong>Διαθεσιμότητα:</strong> η δημοσίευση δεν επιβεβαιώνει εγκατάσταση ή εμπορική ενεργοποίηση.</p><h2 id="v0-7-17-—-2026-11-25" tabindex="-1">v0.7.17 — 2026-11-25 <a class="header-anchor" href="#v0-7-17-—-2026-11-25" aria-label="Permalink to &quot;v0.7.17 — 2026-11-25&quot;">​</a></h2><p>Προγραμματισμός αναθέσεων και επιλογή πληρώματος, ορατότητα επιστροφών στο ημερολόγιο, πίνακας οδηγού, εκκρεμή υπόλοιπα μετρητών και επιβεβαίωση είσπραξης. Παράδοση μετρητών από οδηγό στο γραφείο και ημερήσιες συνόψεις διαχείρισης μετρητών.</p><p><strong>Διαθεσιμότητα:</strong> η δημοσίευση δεν επιβεβαιώνει εγκατάσταση ή εμπορική ενεργοποίηση.</p><h2 id="v0-7-16-—-2026-11-25" tabindex="-1">v0.7.16 — 2026-11-25 <a class="header-anchor" href="#v0-7-16-—-2026-11-25" aria-label="Permalink to &quot;v0.7.16 — 2026-11-25&quot;">​</a></h2><p>Τύποι παραμέτρων PostgreSQL κατά την τροποποίηση κρατήσεων συνεργατών· διατηρούνται οι έγκυροι υπολογισμοί συμβατικών τιμών και προμηθειών.</p><p><strong>Διαθεσιμότητα:</strong> η δημοσίευση δεν επιβεβαιώνει εγκατάσταση ή εμπορική ενεργοποίηση.</p><h2 id="v0-7-15-—-2026-11-25" tabindex="-1">v0.7.15 — 2026-11-25 <a class="header-anchor" href="#v0-7-15-—-2026-11-25" aria-label="Permalink to &quot;v0.7.15 — 2026-11-25&quot;">​</a></h2><p>Τροποποιήσεις επιστροφής και ωριαίας υπηρεσίας οδηγού, εκπτώσεις επιστροφής, τιμές και προμήθειες συνεργατών, καθολικό πληρωμών και υπόλοιπα, συμφωνία μετρητών, πίνακας οδηγού, αναζήτηση με τηλέφωνο, ιδιωτικότητα, Website Studio, διαβίβαση συνομιλίας και δείκτες Command Center. Το email παραμένει προαιρετικό.</p><p><strong>Διαθεσιμότητα:</strong> η δημοσίευση δεν επιβεβαιώνει εγκατάσταση ή εμπορική ενεργοποίηση.</p><h2 id="v0-7-14-—-δημοσιευμενη-εκδοση" tabindex="-1">v0.7.14 — δημοσιευμένη έκδοση <a class="header-anchor" href="#v0-7-14-—-δημοσιευμενη-εκδοση" aria-label="Permalink to &quot;v0.7.14 — δημοσιευμένη έκδοση&quot;">​</a></h2><p>Η έκδοση περιγράφει βελτιώσεις προσαρμογής του προγράμματος αναθέσεων σε διαφορετικές οθόνες, πλοήγησης ημερομηνιών και ημερολογίου, συμβατικής τιμολόγησης συνεργατών και απόδοσης κρατήσεων σε συνεργάτες, ειδικών αιτημάτων επιβατών και εσωτερικών σημειώσεων αναθέσεων, εξουσιοδοτημένων παρακάμψεων αναθέσεων με υποχρεωτική αιτιολόγηση ελέγχου, προσχεδίων και αναθεωρήσεων Website Studio στον διακομιστή και διαβίβασης κρατήσεων μέσω συνομιλίας. Το email επιβάτη παραμένει προαιρετικό.</p><p><strong>Τεκμηρίωση έκδοσης:</strong> επαληθευμένη υπογεγραμμένη ετικέτα έκδοσης και κανονική αναθεώρηση κώδικα <code>bb02dba6eed8c118f86c6a901f569a4da0033067</code>. Η καταγραφή έκδοσης αναφέρει τέσσερις επιτυχείς ροές CI, ελέγχους συνέπειας εκδόσεων και διατήρηση ιστορικών μεταβολών σχήματος· δεν απαιτείται νέα μεταβολή σχήματος από αυτή την έκδοση.</p><p><strong>Διαθεσιμότητα:</strong> δημοσιευμένη έκδοση, όχι ανεξάρτητη επιβεβαίωση εγκατάστασης ή αποδοχής σε λειτουργία. Η δημόσια δημοσίευση και η ενεργοποίηση εξωτερικών παρόχων παραμένουν υπό έγκριση. Η ανάπτυξη λειτουργιών συνεχίζεται πρώτα στα αγγλικά.</p><h2 id="v0-7-13-—-δημοσιευμενη-δοκιμαστικη-εκδοση" tabindex="-1">v0.7.13 — δημοσιευμένη δοκιμαστική έκδοση <a class="header-anchor" href="#v0-7-13-—-δημοσιευμενη-δοκιμαστικη-εκδοση" aria-label="Permalink to &quot;v0.7.13 — δημοσιευμένη δοκιμαστική έκδοση&quot;">​</a></h2><p>Ενσωμάτωση εμπορικών λειτουργιών, εμπορικών αναλύσεων, ετοιμότητας παρόχων πληρωμών, βελτιωμένης διαχείρισης χειριστών και κρατήσεων, υποδομής δημόσιας πύλης κρατήσεων και αναζήτησης επιβατών, καθώς και διασύνδεσης Website Studio και Template Manager.</p><p><strong>Τεκμηρίωση έκδοσης:</strong> η καταγραφή αναφέρει έξι πρόσθετες μεταβολές σχήματος στη δοκιμαστική βάση, περιορισμένα δικαιώματα και τέσσερις επιτυχείς ροές CI. Η ενεργοποίηση δημόσιων κρατήσεων και εξωτερικών διασυνδέσεων απαιτεί χωριστή διαμόρφωση και αποδοχή.</p><h2 id="v0-7-12-—-δημοσιευμενη-δοκιμαστικη-εκδοση" tabindex="-1">v0.7.12 — δημοσιευμένη δοκιμαστική έκδοση <a class="header-anchor" href="#v0-7-12-—-δημοσιευμενη-δοκιμαστικη-εκδοση" aria-label="Permalink to &quot;v0.7.12 — δημοσιευμένη δοκιμαστική έκδοση&quot;">​</a></h2><p>Η εξουσιοδοτημένη προετοιμασία σχεδιασμού ιστοσελίδων υποστηρίζει μεγαλύτερα αιτήματα μέσω ειδικού προστατευμένου σημείου API, διατηρώντας τα συνήθη όρια αιτημάτων. Προηγούνται έλεγχοι εταιρείας και ρόλου, με βελτιωμένη αντιμετώπιση μη έγκυρων ή υπερμεγέθων αιτημάτων. Διατηρούνται οι προστασίες φιλοξενίας, HTTPS και δημοσίευσης και η συμβατότητα με τον ανεξάρτητο χώρο σχεδιασμού.</p><p><strong>Τεκμηρίωση έκδοσης:</strong> η καταγραφή αναφέρει πέντε επιτυχείς ελέγχους αποδοχής CI, υπογεγραμμένη ετικέτα έκδοσης, επαλήθευση απομόνωσης εταιρειών στην PostgreSQL και καμία νέα μεταβολή σχήματος. Δεν συνεπάγεται αυτόματη δημόσια δημοσίευση ιστοσελίδων ή ενεργοποίηση ζωντανών κρατήσεων και πληρωμών.</p><h2 id="v0-7-11-—-ελεγχομενη-δοκιμαστικη-εκδοση-24-νοεμβριου-2026" tabindex="-1">v0.7.11 — ελεγχόμενη δοκιμαστική έκδοση (24 Νοεμβρίου 2026) <a class="header-anchor" href="#v0-7-11-—-ελεγχομενη-δοκιμαστικη-εκδοση-24-νοεμβριου-2026" aria-label="Permalink to &quot;v0.7.11 — ελεγχόμενη δοκιμαστική έκδοση (24 Νοεμβρίου 2026)&quot;">​</a></h2><p>Η έκδοση εισάγει δυνατότητες ενσωματωμένης δημοσίευσης στο Website Studio: διαχείριση φιλοξενίας, επαλήθευση HTTPS, μεταγλώττιση επιλεγμένου σχεδιασμού ιστοσελίδας, προετοιμασία ιδιωτικών αναθεωρήσεων, επαληθευμένα αντίγραφα ασφαλείας και ενημερώσεις ή επαναφορά ιστοσελίδας με εξουσιοδότηση ιδιοκτήτη. Περιλαμβάνει εξουσιοδότηση μίας χρήσης, προστασίες ανάκτησης και συμβατότητα με τον ανεξάρτητο τοπικό χώρο σχεδιασμού.</p><p><strong>Διαθεσιμότητα:</strong> δημοσιευμένη έκδοση λογισμικού μόνο για ελεγχόμενη εγκατάσταση σε δοκιμαστικό περιβάλλον. Δεν αποτελεί απόδειξη ενεργής ιστοσελίδας πελάτη, ζωντανών κρατήσεων ή επεξεργασίας πληρωμών. Δεν περιλαμβάνει μεταβολές σχήματος βάσης δεδομένων ή αλλαγές σε παραγωγικές ιστοσελίδες.</p><h2 id="v0-7-10-—-ελεγχομενη-δοκιμαστικη-εκδοση-24-νοεμβριου-2026" tabindex="-1">v0.7.10 — ελεγχόμενη δοκιμαστική έκδοση (24 Νοεμβρίου 2026) <a class="header-anchor" href="#v0-7-10-—-ελεγχομενη-δοκιμαστικη-εκδοση-24-νοεμβριου-2026" aria-label="Permalink to &quot;v0.7.10 — ελεγχόμενη δοκιμαστική έκδοση (24 Νοεμβρίου 2026)&quot;">​</a></h2><p>Οι βελτιώσεις του Website Studio περιλαμβάνουν οπτική επεξεργασία και προεπισκόπηση συσκευών, πολύγλωσσες ιστοσελίδες αναφοράς (αγγλικά, ελληνικά, ιταλικά, γαλλικά, γερμανικά και ισπανικά), επεξεργασία ενοτήτων και ιδιοτήτων, αυτόματη τοπική αποθήκευση προσχεδίων, αντίγραφα ασφαλείας και ανάκτηση, απομόνωση προσχεδίων ανά εταιρεία, φορητά πακέτα <code>.tbsite.json</code> και <code>.tbtheme.json</code> και βελτιωμένη πλοήγηση μεταξύ Website Studio και Theme Manager.</p><p><strong>Διαθεσιμότητα:</strong> δημοσιευμένη έκδοση λογισμικού μόνο για ελεγχόμενη εγκατάσταση σε δοκιμαστικό περιβάλλον. Η δημόσια δημοσίευση ιστοσελίδων, η αποθήκευση στον διακομιστή που απαιτεί τη μεταβολή σχήματος 020, οι ζωντανές πληρωμές και οι εξωτερικές διασυνδέσεις κρατήσεων δεν ενεργοποιήθηκαν από αυτή την έκδοση.</p><h2 id="v0-7-9-—-εκδοση-αναφορας-κωδικα" tabindex="-1">v0.7.9 — έκδοση αναφοράς κώδικα <a class="header-anchor" href="#v0-7-9-—-εκδοση-αναφορας-κωδικα" aria-label="Permalink to &quot;v0.7.9 — έκδοση αναφοράς κώδικα&quot;">​</a></h2><p>Τοπικό Website Studio πολλαπλών σελίδων, προεπισκόπηση συσκευών, φορητά πακέτα και προσχέδια ανά εταιρεία και τρόπο λειτουργίας. Η ενεργοποίηση βάσης δεδομένων και η δημοσίευση αποτελούν ξεχωριστά στάδια αποδοχής.</p><h2 id="v0-7-8-—-ιστορικη-δοκιμαστικη-εκδοση" tabindex="-1">v0.7.8 — ιστορική δοκιμαστική έκδοση <a class="header-anchor" href="#v0-7-8-—-ιστορικη-δοκιμαστικη-εκδοση" aria-label="Permalink to &quot;v0.7.8 — ιστορική δοκιμαστική έκδοση&quot;">​</a></h2><p>Οι καταγραφές περιγράφουν ασφαλή επανάληψη δημιουργίας κράτησης, προαιρετικό email, αποφυγή διπλοεγγραφών και ρητή συγκατάθεση μηνυμάτων. Η δοκιμαστική αποδοχή δεν πιστοποιεί εμπορική διαθεσιμότητα.</p><h2 id="πολιτικη-εκδοσεων" tabindex="-1">Πολιτική εκδόσεων <a class="header-anchor" href="#πολιτικη-εκδοσεων" aria-label="Permalink to &quot;Πολιτική εκδόσεων&quot;">​</a></h2><p>Οι σημειώσεις εκδόσεων καταγράφουν δημοσιευμένες και ιστορικές εκδόσεις, όχι την τρέχουσα εγκατάσταση ή εμπορική διαθεσιμότητα. Οι υπόλοιποι οδηγοί διατηρούν την έκδοση αναφοράς τους μέχρι να ολοκληρωθεί η επαλήθευση για νεότερη έκδοση. Επιβεβαιώστε την πραγματική έκδοση και τις ενεργές δυνατότητες πριν εφαρμόσετε οδηγίες.</p>',45)])])}const b=e(n,[["render",i]]);export{c as __pageData,b as default};
